"""Generate derived release-version files from VERSION (the single source of truth)."""
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
version = (ROOT / "VERSION").read_text(encoding="utf-8").strip()
if not version:
    raise SystemExit("VERSION is empty")
(ROOT / "sw-version.js").write_text(
    "// Generated by tools/sync_version.py from VERSION; do not edit manually.\n"
    f'const SW_VERSION = "weather-v{version}";\n',
    encoding="utf-8",
)
print(f"version={version}")
